class Solution {
    string host(const string& url) {
        size_t start = url.find("//");
        start = start == string::npos ? 0 : start + 2;
        size_t end = url.find('/', start);
        return url.substr(start, end == string::npos ? string::npos : end - start);
    }

public:
    vector<string> crawl(string startUrl, HtmlParser htmlParser) {
        const string requiredHost = host(startUrl);
        unordered_set<string> visited = {startUrl};
        queue<string> pending;
        pending.push(startUrl);
        mutex lock;
        condition_variable cv;
        int active = 0;
        bool done = false;

        auto worker = [&]() {
            while (true) {
                string url;
                {
                    unique_lock<mutex> guard(lock);
                    cv.wait(guard, [&]() { return done || !pending.empty(); });
                    if (done && pending.empty()) {
                        return;
                    }
                    url = pending.front();
                    pending.pop();
                    ++active;
                }
                vector<string> links = htmlParser.getUrls(url);
                {
                    lock_guard<mutex> guard(lock);
                    for (const string& next : links) {
                        if (host(next) == requiredHost && visited.insert(next).second) {
                            pending.push(next);
                        }
                    }
                    --active;
                    if (pending.empty() && active == 0) {
                        done = true;
                    }
                }
                cv.notify_all();
            }
        };

        vector<thread> threads;
        for (int i = 0; i < 8; ++i) {
            threads.emplace_back(worker);
        }
        for (thread& t : threads) {
            t.join();
        }
        return vector<string>(visited.begin(), visited.end());
    }
};
